SELECT entry, 10, Method, ZoneOrSort, MinLevel, MaxLevel, QuestLevel, Type, RequiredClasses, RequiredRaces, RequiredSkill, RequiredSkillValue, RequiredCondition, RepObjectiveFaction, RepObjectiveValue, RequiredMinRepFaction, RequiredMinRepValue, RequiredMaxRepFaction, RequiredMaxRepValue, SuggestedPlayers, LimitTime, QuestFlags, SpecialFlags, PrevQuestId, NextQuestId, ExclusiveGroup, BreadcrumbForQuestId, NextQuestInChain, SrcItemId, SrcItemCount, SrcSpell, 'Jordas kall', 'Ta denne rå kvartsen frå mæg å kom med han te Canaga Earthcaller som bevis på møtet vårt. Han skal lage ein totem te dæg, å denne steinen skal bli hjartet i han. Så liten som han ser ut, skal du oppdage at storleiken ikje spelar rolle, å at sjølv dei minste tinga kan vare lenger enn mange andre.$B$BVær tolmodig, $N. Hald dæg sterk. Å søk visdom. Dæ æ dæ jorda ber om. Til slutt skal du bli eitt med jorda--respekter ho som ho skal respektere dæg.', 'Kom med Rough Quartz te Canaga Earthcaller i Valley of Trials.', 'Framifrå!$B$BTotemet æg skal lage te dæg æ meir enn eit symbol på statusen din blant $C--han har evner utover dæ. Éi bruk av totemet æ som fokus for trylleformlar. Dei trylleformlane æ knytt te jorda, å etter kvart som du får større visdom, skal fleire av jorda sine evner bli tilgjengelege for dæg.$B$BTrenarane skal vite når du æ klar for større kunnskap.$B$BMen no, ta dette Earth Totem, å ei skriftrull som lærer dæg di fyrste evne.$b$bDæ æ jabnå så dræge.', 'Æg vil vera den første te å ønske dæg fullt velkomen te den fyrste av fire vegar som for alltid skal leie dæ i skjebnen din.$B$BOm du har steinen jorda gav dæg, skal æg gi dæg totemet han lova.$B$BOm ikje, så forsvinn frå mæg te du har funne vegen din.', EndText, ObjectiveText1, ObjectiveText2, ObjectiveText3, ObjectiveText4, ReqItemId1, ReqItemId2, ReqItemId3, ReqItemId4, ReqItemCount1, ReqItemCount2, ReqItemCount3, ReqItemCount4, ReqSourceId1, ReqSourceId2, ReqSourceId3, ReqSourceId4, ReqSourceCount1, ReqSourceCount2, ReqSourceCount3, ReqSourceCount4, ReqCreatureOrGOId1, ReqCreatureOrGOId2, ReqCreatureOrGOId3, ReqCreatureOrGOId4, ReqCreatureOrGOCount1, ReqCreatureOrGOCount2, ReqCreatureOrGOCount3, ReqCreatureOrGOCount4, ReqSpellCast1, ReqSpellCast2, ReqSpellCast3, ReqSpellCast4, RewChoiceItemId1, RewChoiceItemId2, RewChoiceItemId3, RewChoiceItemId4, RewChoiceItemId5, RewChoiceItemId6, RewChoiceItemCount1, RewChoiceItemCount2, RewChoiceItemCount3, RewChoiceItemCount4, RewChoiceItemCount5, RewChoiceItemCount6, RewItemId1, RewItemId2, RewItemId3, RewItemId4, RewItemCount1, RewItemCount2, RewItemCount3, RewItemCount4, RewRepFaction1, RewRepFaction2, RewRepFaction3, RewRepFaction4, RewRepFaction5, RewRepValue1, RewRepValue2, RewRepValue3, RewRepValue4, RewRepValue5, RewRepSpilloverMask, RewXP, RewOrReqMoney, RewMoneyMaxLevel, RewSpell, RewSpellCast, RewMailTemplateId, RewMailDelaySecs, RewMailMoney, PointMapId, PointX, PointY, PointOpt, DetailsEmote1, DetailsEmote2, DetailsEmote3, DetailsEmote4, DetailsEmoteDelay1, DetailsEmoteDelay2, DetailsEmoteDelay3, DetailsEmoteDelay4, IncompleteEmote, CompleteEmote, OfferRewardEmote1, OfferRewardEmote2, OfferRewardEmote3, OfferRewardEmote4, OfferRewardEmoteDelay1, OfferRewardEmoteDelay2, OfferRewardEmoteDelay3, OfferRewardEmoteDelay4, StartScript, CompleteScript
FROM quest_template WHERE entry = 1518 AND patch = 0;

