SELECT entry, 10, Method, ZoneOrSort, MinLevel, MaxLevel, QuestLevel, Type, RequiredClasses, RequiredRaces, RequiredSkill, RequiredSkillValue, RequiredCondition, RepObjectiveFaction, RepObjectiveValue, RequiredMinRepFaction, RequiredMinRepValue, RequiredMaxRepFaction, RequiredMaxRepValue, SuggestedPlayers, LimitTime, QuestFlags, SpecialFlags, PrevQuestId, NextQuestId, ExclusiveGroup, BreadcrumbForQuestId, NextQuestInChain, SrcItemId, SrcItemCount, SrcSpell, 'Glyfeskrift-tavle', 'Ah, medan du va borte kom dæ ei tavle te dæg, $N.$B$BLes dæ når du har tid. Om æg ikje tar feil, kom dæ frå magitreinaren Mai\'ah. Ho vil snakke med dæg når du æ klar.', 'Les Glyphic Tablet å snakk med Mai\'ah nær inngangen te Den i Valley of Trials.', 'Du æ blant dei mektigaste vesena på planeten, $N... dæ æ ikje tvil om dæ. Å alle veit dæ... veit dæ godt, også!$B$BMen du må vera på vakt! For dæ æ ikje orken, eller alven, eller dvergen du skal vera redd for... dæ æ tinga du ikje kan sjå. Magi æ mektig. Dæ får dæg te å gjera ting du kanskje ikje vil gjera. Dæ får dæg te å tru du æ meir mektig enn du verkeleg æ. Vær tolmodig. Vær smart.$B$BNår du trur du æ klar for trening, kom tebake te Mai\'ah. Ho lærer dæg dæ du æ klar for å lære, ikje noko problem.$b$bDæ æ jabnå så dræge.', 'Du ser ut te å glede Mai\'ah alt, $N. Dæ æ bra. Du gir Mai\'ah respekt, å Mai\'ah gir kanskje respekt tebake. Men nok om dæ, du æ her for å lære om magi, ikje høyre Mai\'ah snakke.$B$BDæ æ berre ein ting Mai\'ah ikje kan lære dæg om magi, $N, å dæ æ korleis du stoppar fordervinga.', EndText, ObjectiveText1, ObjectiveText2, ObjectiveText3, ObjectiveText4, ReqItemId1, ReqItemId2, ReqItemId3, ReqItemId4, ReqItemCount1, ReqItemCount2, ReqItemCount3, ReqItemCount4, ReqSourceId1, ReqSourceId2, ReqSourceId3, ReqSourceId4, ReqSourceCount1, ReqSourceCount2, ReqSourceCount3, ReqSourceCount4, ReqCreatureOrGOId1, ReqCreatureOrGOId2, ReqCreatureOrGOId3, ReqCreatureOrGOId4, ReqCreatureOrGOCount1, ReqCreatureOrGOCount2, ReqCreatureOrGOCount3, ReqCreatureOrGOCount4, ReqSpellCast1, ReqSpellCast2, ReqSpellCast3, ReqSpellCast4, RewChoiceItemId1, RewChoiceItemId2, RewChoiceItemId3, RewChoiceItemId4, RewChoiceItemId5, RewChoiceItemId6, RewChoiceItemCount1, RewChoiceItemCount2, RewChoiceItemCount3, RewChoiceItemCount4, RewChoiceItemCount5, RewChoiceItemCount6, RewItemId1, RewItemId2, RewItemId3, RewItemId4, RewItemCount1, RewItemCount2, RewItemCount3, RewItemCount4, RewRepFaction1, RewRepFaction2, RewRepFaction3, RewRepFaction4, RewRepFaction5, RewRepValue1, RewRepValue2, RewRepValue3, RewRepValue4, RewRepValue5, RewRepSpilloverMask, RewXP, RewOrReqMoney, RewMoneyMaxLevel, RewSpell, RewSpellCast, RewMailTemplateId, RewMailDelaySecs, RewMailMoney, PointMapId, PointX, PointY, PointOpt, DetailsEmote1, DetailsEmote2, DetailsEmote3, DetailsEmote4, DetailsEmoteDelay1, DetailsEmoteDelay2, DetailsEmoteDelay3, DetailsEmoteDelay4, IncompleteEmote, CompleteEmote, OfferRewardEmote1, OfferRewardEmote2, OfferRewardEmote3, OfferRewardEmote4, OfferRewardEmoteDelay1, OfferRewardEmoteDelay2, OfferRewardEmoteDelay3, OfferRewardEmoteDelay4, StartScript, CompleteScript
FROM quest_template WHERE entry = 3086 AND patch = 0;

